UPDATE inventories
SET
    available_quantity = available_quantity - #{quantity},
    version = version + 1
WHERE product_id = #{productId}
    AND available_quantity >= #{quantity}
    AND version = #{version}

UPDATE inventories
SET
available_quantity = available_quantity + #{quantity},
version = version + 1
WHERE product_id = #{productId}
AND version = #{version}
